, IS_ATTACH_CD
) VALUES ( #{id}, #{prjId}, #{subject}, #{description}, #{categoryCd}, #{priorityCd}, SYSDATE, #{updatedOn}, #{estStartDate}, #{dueDate}, #{startDate}, #{closedDate}, #{parentIssue}, #{rootIssue}, #{memId}, #{lft}, #{rgt}, #{doneRatio}, #{writer}
