UPDATE ISSUE
SUBJECT = #{subject}, DESCRIPTION = #{description}, CATEGORY_CD = #{categoryCd}, STATUS_CD = #{statusCd}, PRIORITY_CD = #{priorityCd}, EST_START_DATE = #{estStartDate}, DUE_DATE = #{dueDate}, START_DATE = #{startDate}, CLOSED_DATE = #{closedDate}, PARENT_ISSUE = #{parentIssue}, ROOT_ISSUE = #{rootIssue}, MEM_ID = #{memId}, LFT = #{lft}, RGT = #{rgt}, DONE_RATIO = #{doneRatio}, IS_ATTACH_CD = #{isAttachCd}, UPDATED_ON = SYSDATE, last_updater = #{lastUpdater}
WHERE ID = #{id}

UPDATE ISSUE SET (START_DATE, UPDATED_ON,last_updater) = (SELECT SYSDATE, SYSDATE,#{updater} FROM DUAL) WHERE ID IN
#{id}
and start_date is null

UPDATE ISSUE
STATUS_CD = #{statusCd}, DONE_RATIO = CASE WHEN #{statusCd} = '01ISSUESTAT' THEN 0 WHEN #{statusCd} IN ('03ISSUESTAT','04ISSUESTAT') THEN 100 WHEN #{statusCd} = '02ISSUESTAT' THEN LEAST(90, GREATEST(10, ROUND(NVL(DONE_RATIO,0)/10)*10)) END,
PRIORITY_CD = #{priorityCd}, CATEGORY_CD = #{categoryCd}, UPDATED_ON = SYSDATE, last_updater = #{updater}
WHERE ID IN #{id}

